#include <algorithm>
#include <climits>
#include <fstream>
#include <set>
#include <vector>
using namespace std;
int main() {
    ifstream in("maxflow.in"); ofstream out("maxflow.out");
    int n,k; if (!(in>>n>>k)) return 0;
    vector<vector<int>> g(n+1);
    for(int i=1,u,v;i<n;i++){in>>u>>v;g[u].push_back(v);g[v].push_back(u);}
    int lg=1; while((1<<lg)<=n) ++lg;
    vector<vector<int>> up(lg,vector<int>(n+1));
    vector<int> depth(n+1),order{1};
    for(size_t i=0;i<order.size();i++){
        int u=order[i];
        for(int v:g[u]) if(v!=up[0][u]){up[0][v]=u;depth[v]=depth[u]+1;order.push_back(v);}
    }
    for(int b=1;b<lg;b++)for(int u=1;u<=n;u++)up[b][u]=up[b-1][up[b-1][u]];
    auto lca=[&](int u,int v){
        if(depth[u]<depth[v])swap(u,v);
        int diff=depth[u]-depth[v];
        for(int b=0;b<lg;b++)if(diff&(1<<b))u=up[b][u];
        if(u==v)return u;
        for(int b=lg-1;b>=0;b--)if(up[b][u]!=up[b][v]){u=up[b][u];v=up[b][v];}
        return up[0][u];
    };
    vector<long long> delta(n+1);
    for(int i=0,s,t;i<k;i++){
        in>>s>>t;int w=lca(s,t);
        ++delta[s];++delta[t];--delta[w];if(up[0][w])--delta[up[0][w]];
    }
    for(int i=n-1;i>0;i--)delta[up[0][order[i]]]+=delta[order[i]];
    out<<*max_element(delta.begin()+1,delta.end())<<'\n';
}
