#include <algorithm>
#include <climits>
#include <fstream>
#include <set>
#include <vector>
using namespace std;
int main(){
    ifstream in("cardgame.in");ofstream out("cardgame.out");
    int n;if(!(in>>n))return 0;
    vector<int> e(n),hi(n+1),lo(n+1);vector<bool> used(2*n+1);
    for(int&v:e){in>>v;used[v]=true;}
    set<int> hand;for(int v=1;v<=2*n;v++)if(!used[v])hand.insert(v);
    auto high=hand;
    for(int i=0;i<n;i++){
        hi[i+1]=hi[i];auto it=high.upper_bound(e[i]);
        if(it!=high.end()){++hi[i+1];high.erase(it);}
    }
    auto low=hand;
    for(int i=n-1;i>=0;i--){
        lo[i]=lo[i+1];auto it=low.lower_bound(e[i]);
        if(it!=low.begin()){--it;++lo[i];low.erase(it);}
    }
    int answer=0;for(int k=0;k<=n;k++)answer=max(answer,hi[k]+lo[k]);
    out<<answer<<'\n';
}
