#include <algorithm>
#include <climits>
#include <fstream>
#include <set>
#include <vector>
using namespace std;
struct Tree{
    int n;vector<long long> sum,mn,lazy;
    Tree(const vector<long long>&a):n((int)a.size()),sum(4*n),mn(4*n),lazy(4*n){build(1,0,n-1,a);}
    void pull(int p){sum[p]=sum[2*p]+sum[2*p+1];mn[p]=min(mn[2*p],mn[2*p+1]);}
    void build(int p,int l,int r,const vector<long long>&a){
        if(l==r){sum[p]=mn[p]=a[l];return;}
        int m=(l+r)/2;build(2*p,l,m,a);build(2*p+1,m+1,r,a);pull(p);
    }
    void apply(int p,int l,int r,long long c){sum[p]+=c*(r-l+1);mn[p]+=c;lazy[p]+=c;}
    void push(int p,int l,int r){
        if(l!=r && lazy[p]){int m=(l+r)/2;apply(2*p,l,m,lazy[p]);apply(2*p+1,m+1,r,lazy[p]);lazy[p]=0;}
    }
    void add(int p,int l,int r,int a,int b,long long c){
        if(a<=l&&r<=b){apply(p,l,r,c);return;}
        push(p,l,r);int m=(l+r)/2;
        if(a<=m)add(2*p,l,m,a,b,c);if(b>m)add(2*p+1,m+1,r,a,b,c);pull(p);
    }
    pair<long long,long long> query(int p,int l,int r,int a,int b){
        if(a<=l&&r<=b)return {sum[p],mn[p]};
        push(p,l,r);int m=(l+r)/2;pair<long long,long long> x={0,LLONG_MAX};
        if(a<=m){auto y=query(2*p,l,m,a,b);x.first+=y.first;x.second=min(x.second,y.second);}
        if(b>m){auto y=query(2*p+1,m+1,r,a,b);x.first+=y.first;x.second=min(x.second,y.second);}
        return x;
    }
};
int main(){
    ifstream in("haybales.in");ofstream out("haybales.out");
    int n,q;if(!(in>>n>>q))return 0;vector<long long>a(n);for(auto&x:a)in>>x;Tree t(a);
    while(q--){char c;int l,r;in>>c>>l>>r;--l;--r;
        if(c=='P'){long long v;in>>v;t.add(1,0,n-1,l,r,v);}
        else{auto x=t.query(1,0,n-1,l,r);out<<(c=='S'?x.first:x.second)<<'\n';}
    }
}
